import type { HTMLAttributes } from 'react';
import { cx } from '@/lib/cx';
import { useStrings } from '@/lib/i18n';
import './avatar.css';

/**
 * B30 · Avatar — a person, named. Initials on wall by default; a photo
 * only when the product genuinely has one. Never decorative, never a
 * generic silhouette, never the sole carrier of the name (A4).
 */
export interface AvatarProps extends Omit<HTMLAttributes<HTMLElement>, 'children'> {
  /** The full name. Initials and the accessible name both come from it. */
  name: string;
  src?: string;
  size?: 'sm' | 'md' | 'lg';
  /** Marks the current user / active member — one per group, like all seed. */
  tone?: 'neutral' | 'seed';
  className?: string;
}

function initials(name: string) {
  const parts = name.trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return '';
  const first = parts[0][0] ?? '';
  const last = parts.length > 1 ? (parts[parts.length - 1][0] ?? '') : '';
  return (first + last).toUpperCase();
}

const PX = { sm: 24, md: 32, lg: 44 } as const;

export function Avatar({ name, src, size = 'md', tone = 'neutral', className, ...rest }: AvatarProps) {
  const cls = cx('sv-avatar', `sv-avatar--${size}`, tone === 'seed' && 'sv-avatar--seed', className);
  /* The intrinsic size matches the drawn one, so the browser reserves the
     right box before the photo loads (no layout shift) at every size. */
  const px = PX[size];
  if (src) return <img {...rest} className={cls} src={src} alt={name} width={px} height={px} />;
  return (
    <span {...rest} className={cls} role="img" aria-label={name}>
      <span aria-hidden="true">{initials(name)}</span>
    </span>
  );
}

export interface AvatarGroupProps extends Omit<HTMLAttributes<HTMLSpanElement>, 'children'> {
  people: { name: string; src?: string }[];
  /** Faces shown before the overflow count. Default 4. */
  max?: number;
  size?: 'sm' | 'md';
  className?: string;
}

/**
 * The overlapped stack, capped. The overflow chip is mono and states the
 * count; the full list belongs in a Drawer or a table, never in a hover.
 */
export function AvatarGroup({ people, max = 4, size = 'sm', className, ...attrs }: AvatarGroupProps) {
  const tr = useStrings();
  const shown = people.slice(0, max);
  const rest = people.length - shown.length;
  return (
    <span {...attrs} className={cx('sv-avatars', className)}>
      {shown.map((person) => (
        <Avatar key={person.name} name={person.name} src={person.src} size={size} />
      ))}
      {rest > 0 && (
        <span className={cx('sv-avatar', `sv-avatar--${size}`, 'sv-avatar--rest', 'sv-mono')} role="img" aria-label={tr.more(rest)}>
          <span aria-hidden="true">+{rest}</span>
        </span>
      )}
    </span>
  );
}

/* B30 · Avatar — initials on wall, 50% radius (a registered exception to
   the one-radius rule, alongside status dots). Images never move (Part E). */

@layer sv-components {
  .sv-avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    border-radius: 50%;
    background: var(--sv-wall);
    color: var(--sv-ink-soft);
    font-weight: 700;
    letter-spacing: 0.01em;
    object-fit: cover;
    overflow: hidden;
  }

  .sv-avatar--sm {
    width: 24px;
    height: 24px;
    font-size: 10px;
  }

  .sv-avatar--md {
    width: 32px;
    height: 32px;
    font-size: 11.5px;
  }

  .sv-avatar--lg {
    width: 44px;
    height: 44px;
    font-size: 15px;
  }

  .sv-avatar--seed {
    background: var(--sv-seed-tint);
    color: var(--sv-seed-text);
  }

  .sv-avatars {
    display: inline-flex;
    align-items: center;
  }

  /* The overlap is a ring of the surface behind, not a shadow. */
  .sv-avatars .sv-avatar + .sv-avatar {
    margin-inline-start: -6px;
  }

  .sv-avatars .sv-avatar {
    box-shadow: inset 0 0 0 1.5px var(--sv-paper);
  }

  .sv-avatars .sv-avatar--rest {
    background: var(--sv-paper);
    color: var(--sv-ink-soft);
    font-size: 10px;
    letter-spacing: 0;
    box-shadow: inset 0 0 0 1px var(--sv-line);
  }
}
